"""Stock items."""
import warnings
from . import units


class Item:
    """A line of stock: sku, quantity in grams and a price per kilogram in cents."""

    def __init__(self, sku, qty, unit, price_cents):
        self.sku = sku
        self.grams = units.to_base(qty, unit)
        self.price_cents = price_cents

    def worth(self, *args, **kwargs):
        """Deprecated alias of value_cents()."""
        warnings.warn("Item.worth is deprecated, use value_cents", DeprecationWarning, stacklevel=2)
        return self.value_cents(*args, **kwargs)

    def value_cents(self):
        """Value of the line in cents."""
        return self.grams * self.price_cents // 1000

    def label(self):
        return "%s (%s)" % (self.sku, units.pretty(self.grams))


def make_item(row):
    """Build an item from a (sku, qty, unit, price_cents) row."""
    sku, qty, unit, price = row
    return Item(sku, qty, unit, price)


def __getattr__(name):
    """Deprecated alias StockItem of Item (PEP 562), so that isinstance checks keep working."""
    if name == "StockItem":
        warnings.warn("StockItem is deprecated, use Item", DeprecationWarning, stacklevel=2)
        return Item
    raise AttributeError("module %r has no attribute %r" % (__name__, name))

