import json
import unittest

from stockroom import cli, items as items_mod, pricing, report, units
from stockroom.items import StockItem


def run_case(case):
    its = [items_mod.make_item(tuple(r)) for r in case["rows"]]
    direct = StockItem("Z9", case["qty"], case["unit"], case["price"])
    return {
        "labels": [i.label() for i in its],
        "worth": [i.worth() for i in its],
        "direct": [direct.worth(), pricing.calc_price(direct, case["extra"])],
        "prices": [pricing.calc_price(i) for i in its],
        "render": [report.render(its), report.render(its, with_header=False)],
        "summary": report.summarize(its),
        "cli": cli.main(case["argv"]),
        "pretty": units.pretty(case["grams"]),
        "base": units.to_base(case["qty"], case["unit"]),
        "isitem": isinstance(direct, items_mod.StockItem),
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"rows\": [[\"E92\", 12, \"g\", 1122]], \"qty\": 5, \"unit\": \"oz\", \"price\": 869, \"extra\": 0, \"argv\": [\"E92:12:g:1122\"], \"grams\": 0}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"labels\": [\"E92 (12 g)\"], \"worth\": [13], \"direct\": [121, 121], \"prices\": [13], \"render\": [\"sku                qty      price\\nE92                12 g        13\", \"E92                12 g        13\"], \"summary\": {\"count\": 1, \"value\": 13, \"after_discount\": 13, \"saved\": 0, \"weight\": \"12 g\"}, \"cli\": {\"text\": \"sku                qty      price\\nE92                12 g        13\", \"summary\": {\"count\": 1, \"value\": 13, \"after_discount\": 13, \"saved\": 0, \"weight\": \"12 g\"}, \"cheapest\": \"E92\"}, \"pretty\": \"0 g\", \"base\": 140, \"isitem\": true}"))

    def test_example_2(self):
        case = json.loads("{\"rows\": [], \"qty\": 3, \"unit\": \"g\", \"price\": 2775, \"extra\": 5, \"argv\": [], \"grams\": 0}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"labels\": [], \"worth\": [], \"direct\": [8, 7], \"prices\": [], \"render\": [\"sku                qty      price\", \"\"], \"summary\": {\"count\": 0, \"value\": 0, \"after_discount\": 0, \"saved\": 0, \"weight\": \"0 g\"}, \"cli\": {\"text\": \"sku                qty      price\", \"summary\": {\"count\": 0, \"value\": 0, \"after_discount\": 0, \"saved\": 0, \"weight\": \"0 g\"}, \"cheapest\": null}, \"pretty\": \"0 g\", \"base\": 3, \"isitem\": true}"))

    def test_example_3(self):
        case = json.loads("{\"rows\": [[\"A39\", 12, \"lb\", 443], [\"A23\", 0.5, \"g\", 896], [\"B80\", 0.5, \"oz\", 1137], [\"D83\", 3, \"oz\", 230]], \"qty\": 3, \"unit\": \"g\", \"price\": 2207, \"extra\": 0, \"argv\": [\"A39:12:lb:443\", \"A23:0.5:g:896\", \"B80:0.5:oz:1137\", \"D83:3:oz:230\"], \"grams\": 15}")
