"""Late fees."""
import warnings
from .loans import LoanRecord


def fine_for(record, today, waive=False):
    """Fine in cents: 25 per late day, capped at 1000; zero when waived."""
    if not isinstance(record, LoanRecord):
        raise TypeError("expected a LoanRecord")
    if waive:
        return 0
    return min(1000, 25 * record.overdue_days(today))


def calc_fine(*args, **kwargs):
    """Deprecated alias of fine_for."""
    warnings.warn("calc_fine is deprecated, use fine_for", DeprecationWarning, stacklevel=2)
    return fine_for(*args, **kwargs)

