"""Time entries."""
import warnings
from . import durations


class Booking:
    """Time booked on a task at an hourly rate (cents)."""

    def __init__(self, task, span, rate_cents=0):
        self.task = task
        self.span = span
        self.rate_cents = rate_cents

    def minutes(self, *args, **kwargs):
        """Deprecated alias of length_min()."""
        warnings.warn("Booking.minutes is deprecated, use length_min", DeprecationWarning, stacklevel=2)
        return self.length_min(*args, **kwargs)

    def length_min(self):
        """Duration in minutes."""
        return durations.parse_span(self.span)

    def pretty(self):
        return "%s %s" % (self.task, durations.format_span(self.length_min()))


def load_entries(rows):
    """Entries from (task, span, rate_cents) rows."""
    return [Booking(task, span, rate) for task, span, rate in rows]


def __getattr__(name):
    """Deprecated alias TimeEntry of Booking (PEP 562), so that isinstance checks keep working."""
    if name == "TimeEntry":
        warnings.warn("TimeEntry is deprecated, use Booking", DeprecationWarning, stacklevel=2)
        return Booking
    raise AttributeError("module %r has no attribute %r" % (__name__, name))

