"""Billing."""
import warnings
from .entries import Entry


def cost_cents(entry):
    """Cost of an entry in cents, rounded half up per entry."""
    if not isinstance(entry, Entry):
        raise TypeError("expected a Entry")
    return (entry.duration_minutes() * entry.rate_cents + 30) // 60


def invoice_lines(entries, merge_tasks=True, **legacy):
    """(task, minutes, cents) lines; same-named tasks are merged when merge_tasks is true."""
    if "group" in legacy:
        warnings.warn("group is deprecated, use merge_tasks", DeprecationWarning, stacklevel=2)
        merge_tasks = legacy.pop("group")
    if legacy:
        raise TypeError("unexpected keyword arguments: " + ", ".join(sorted(legacy)))
    if not merge_tasks:
        return [(e.task, e.duration_minutes(), cost_cents(e)) for e in entries]
    merged = {}
    for e in entries:
        minutes, cents = merged.get(e.task, (0, 0))
        merged[e.task] = (minutes + e.duration_minutes(), cents + cost_cents(e))
    return [(t, m, c) for t, (m, c) in sorted(merged.items())]


def hourly_cost(*args, **kwargs):
    """Deprecated alias of cost_cents."""
    warnings.warn("hourly_cost is deprecated, use cost_cents", DeprecationWarning, stacklevel=2)
    return cost_cents(*args, **kwargs)

