"""Loans and due dates."""
import warnings
from datetime import timedelta

from .catalog import Book

LOAN_DAYS = 21


class Checkout:
    """A book on loan to a member."""

    def __init__(self, book, member, start):
        if not isinstance(book, Book):
            raise TypeError("book must be a Book")
        self.book = book
        self.member = member
        self.start = start

    def due(self):
        """Last day without a fine."""
        return self.start + timedelta(days=LOAN_DAYS)

    def days_late(self, *args, **kwargs):
        """Deprecated alias of days_overdue()."""
        warnings.warn("Checkout.days_late is deprecated, use days_overdue", DeprecationWarning, stacklevel=2)
        return self.days_overdue(*args, **kwargs)

    def days_overdue(self, today):
        """Whole days past the due date (0 when on time)."""
        return max(0, (today - self.due()).days)


def lend(book, member, start):
    """Lend a copy of the book; raises ValueError when none is left."""
    if book.copies <= 0:
        raise ValueError("no copies left")
    book.copies -= 1
    return Checkout(book, member, start)


def __getattr__(name):
    """Deprecated alias LoanRecord of Checkout (PEP 562), so that isinstance checks keep working."""
    if name == "LoanRecord":
        warnings.warn("LoanRecord is deprecated, use Checkout", DeprecationWarning, stacklevel=2)
        return Checkout
    raise AttributeError("module %r has no attribute %r" % (__name__, name))

