"""Time entries."""
import warnings
from . import timespan


class Entry:
    """Time booked on a task at an hourly rate (cents)."""

    def __init__(self, task, span, rate_cents=0):
        self.task = task
        self.span = span
        self.rate_cents = rate_cents

    def minutes(self, *args, **kwargs):
        """Deprecated alias of duration_minutes()."""
        warnings.warn("Entry.minutes is deprecated, use duration_minutes", DeprecationWarning, stacklevel=2)
        return self.duration_minutes(*args, **kwargs)

    def duration_minutes(self):
        """Duration in minutes."""
        return timespan.parse_span(self.span)

    def pretty(self):
        return "%s %s" % (self.task, timespan.format_span(self.duration_minutes()))


def load_entries(rows):
    """Entries from (task, span, rate_cents) rows."""
    return [Entry(task, span, rate) for task, span, rate in rows]


def __getattr__(name):
    """Deprecated alias TimeEntry of Entry (PEP 562), so that isinstance checks keep working."""
    if name == "TimeEntry":
        warnings.warn("TimeEntry is deprecated, use Entry", DeprecationWarning, stacklevel=2)
        return Entry
    raise AttributeError("module %r has no attribute %r" % (__name__, name))

