import json
import unittest

from tempo import app, billing, entries, spans


def run_case(case):
    rows = [tuple(r) for r in case["rows"]]
    es = entries.load_entries(rows)
    return {
        "minutes": [e.minutes() for e in es],
        "pretty": [e.pretty() for e in es],
        "costs": [billing.hourly_cost(e) for e in es],
        "grouped": billing.invoice_lines(es),
        "flat": billing.invoice_lines(es, group=False),
        "summary": app.summarize(rows, combine=case["combine"]),
        "parse": spans.parse_span(case["span"]),
        "isentry": [isinstance(e, entries.TimeEntry) for e in es],
    }


def norm(x):
    return json.loads(json.dumps(x))


class BasicTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"rows\": [[\"design\", \"3h5m\", 4500]], \"combine\": true, \"span\": \"10m\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"minutes\": [185], \"pretty\": [\"design 3h5m\"], \"costs\": [13875], \"grouped\": [[\"design\", 185, 13875]], \"flat\": [[\"design\", 185, 13875]], \"summary\": {\"lines\": [[\"design\", 185, 13875]], \"total\": 13875, \"time\": \"3h5m\"}, \"parse\": 10, \"isentry\": [true]}"))

    def test_example_2(self):
        case = json.loads("{\"rows\": [[\"build\", \"90m\", 0], [\"build\", \"90m\", 6000], [\"review\", \"0m\", 6000], [\"review\", \"0m\", 4500], [\"build\", \"3h5m\", 8250]], \"combine\": true, \"span\": \"45m\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"minutes\": [90, 90, 0, 0, 185], \"pretty\": [\"build 1h30m\", \"build 1h30m\", \"review 0m\", \"review 0m\", \"build 3h5m\"], \"costs\": [0, 9000, 0, 0, 25438], \"grouped\": [[\"build\", 365, 34438], [\"review\", 0, 0]], \"flat\": [[\"build\", 90, 0], [\"build\", 90, 9000], [\"review\", 0, 0], [\"review\", 0, 0], [\"build\", 185, 25438]], \"summary\": {\"lines\": [[\"build\", 365, 34438], [\"review\", 0, 0]], \"total\": 34438, \"time\": \"6h5m\"}, \"parse\": 45, \"isentry\": [true, true, true, true, true]}"))

    def test_example_3(self):
        case = json.loads("{\"rows\": [], \"combine\": false, \"span\": \"1h\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"minutes\": [], \"pretty\": [], \"costs\": [], \"grouped\": [], \"flat\": [], \"summary\": {\"lines\": [], \"total\": 0, \"time\": \"0m\"}, \"parse\": 60, \"isentry\": []}"))


if __name__ == '__main__':
    unittest.main()
